from enum import Enum

class Mode(Enum):
    SAFE = 'safe'
    NOMINAL = 'nominal'
    SCIENCE = 'science'

class FlightModeMachine:
    RECOVERABLE_FAULTS = {'watchdog', 'undervoltage', 'attitude_loss'}

    def __init__(self, mode=Mode.NOMINAL):
        self.mode = mode
        self.latched_fault = None

    def trip_safe(self, fault):
        if fault not in self.RECOVERABLE_FAULTS:
            return False
        self.mode = Mode.SAFE
        self.latched_fault = fault
        return True

    def exit_safe(self, *, ground_authorized, fault_cleared):
        if self.mode is not Mode.SAFE or not ground_authorized or not fault_cleared:
            return False
        self.mode = Mode.NOMINAL
        self.latched_fault = None
        return True
